<?php
require_once __DIR__ . '/../includes/functions.php'; require_admin();
function validate_book_input(): array { return [ (int)($_POST['id_kategori'] ?? 0), trim($_POST['judul_buku'] ?? ''), trim($_POST['penulis'] ?? ''), trim($_POST['penerbit'] ?? ''), (int)($_POST['tahun_terbit'] ?? 0), (float)($_POST['harga'] ?? -1), (int)($_POST['stok'] ?? -1), trim($_POST['deskripsi'] ?? '') ]; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id_buku']??0);
    try {
        if ($action === 'delete') { $find=$pdo->prepare('SELECT gambar FROM buku WHERE id_buku=?'); $find->execute([$id]); $old=$find->fetch(); $del=$pdo->prepare('DELETE FROM buku WHERE id_buku=?'); $del->execute([$id]); if ($del->rowCount()) delete_upload($old['gambar'] ?? null); set_flash('success','Buku berhasil dihapus.'); redirect('admin/buku.php'); }
        [$category,$title,$author,$publisher,$year,$price,$stock,$description] = validate_book_input();
        if (!$category || $title==='' || $author==='' || $publisher==='' || $year < 1000 || $year > (int)date('Y')+1 || $price < 0 || $stock < 0 || $description === '') throw new RuntimeException('Mohon isi seluruh data buku dengan benar.');
        $image = null; if (($_FILES['gambar']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) { [$ok,$result]=upload_file($_FILES['gambar'],'uploads/books',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']); if (!$ok) throw new RuntimeException($result); $image=$result; }
        if ($action === 'add') { $stmt=$pdo->prepare('INSERT INTO buku (id_kategori,judul_buku,penulis,penerbit,tahun_terbit,harga,stok,deskripsi,gambar) VALUES (?,?,?,?,?,?,?,?,?)'); $stmt->execute([$category,$title,$author,$publisher,$year,$price,$stock,$description,$image]); set_flash('success','Buku berhasil ditambahkan.'); }
        elseif ($action === 'edit') { $oldStmt=$pdo->prepare('SELECT gambar FROM buku WHERE id_buku=?'); $oldStmt->execute([$id]); $old=$oldStmt->fetch(); if (!$old) throw new RuntimeException('Data buku tidak ditemukan.'); $image=$image ?: $old['gambar']; $stmt=$pdo->prepare('UPDATE buku SET id_kategori=?,judul_buku=?,penulis=?,penerbit=?,tahun_terbit=?,harga=?,stok=?,deskripsi=?,gambar=? WHERE id_buku=?'); $stmt->execute([$category,$title,$author,$publisher,$year,$price,$stock,$description,$image,$id]); if (isset($result) && $old['gambar']) delete_upload($old['gambar']); set_flash('success','Data buku berhasil diubah.'); }
    } catch (Throwable $e) { if (isset($image) && $image) delete_upload($image); set_flash('danger',$e->getMessage()); }
    redirect('admin/buku.php');
}
$categories=$pdo->query('SELECT * FROM kategori ORDER BY nama_kategori')->fetchAll(); $edit=null; if(isset($_GET['edit'])) { $stmt=$pdo->prepare('SELECT * FROM buku WHERE id_buku=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch(); }
$q=trim($_GET['q']??''); $stmt=$pdo->prepare('SELECT b.*,k.nama_kategori FROM buku b JOIN kategori k ON k.id_kategori=b.id_kategori WHERE b.judul_buku LIKE ? OR b.penulis LIKE ? ORDER BY b.created_at DESC');$stmt->execute(['%'.$q.'%','%'.$q.'%']);$books=$stmt->fetchAll(); $page_title='Manajemen Buku'; require __DIR__ . '/../includes/admin_header.php';
?>
<div class="admin-toolbar"><div><p class="helper">Tambah, ubah, atau hapus koleksi toko.</p></div><form class="search-inline" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Cari judul atau penulis"><button type="submit">Cari</button></form></div><div class="admin-grid"><section class="card"><h2><?= $edit ? 'Ubah Buku' : 'Tambah Buku' ?></h2><form method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit ? 'edit':'add' ?>"><?php if($edit): ?><input type="hidden" name="id_buku" value="<?= $edit['id_buku'] ?>"><?php endif; ?><div class="form-group"><label>Kategori</label><select name="id_kategori" required><option value="">Pilih kategori</option><?php foreach($categories as $cat): ?><option value="<?= $cat['id_kategori'] ?>" <?= (int)($edit['id_kategori']??0)===(int)$cat['id_kategori']?'selected':'' ?>><?= e($cat['nama_kategori']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Judul buku</label><input name="judul_buku" required value="<?= e($edit['judul_buku']??'') ?>"></div><div class="form-row"><div class="form-group"><label>Penulis</label><input name="penulis" required value="<?= e($edit['penulis']??'') ?>"></div><div class="form-group"><label>Penerbit</label><input name="penerbit" required value="<?= e($edit['penerbit']??'') ?>"></div></div><div class="form-row"><div class="form-group"><label>Tahun terbit</label><input type="number" name="tahun_terbit" min="1000" max="<?= date('Y')+1 ?>" required value="<?= e($edit['tahun_terbit']??date('Y')) ?>"></div><div class="form-group"><label>Harga</label><input type="number" name="harga" min="0" required value="<?= e($edit['harga']??'') ?>"></div></div><div class="form-group"><label>Stok</label><input type="number" name="stok" min="0" required value="<?= e($edit['stok']??0) ?>"></div><div class="form-group"><label>Deskripsi</label><textarea name="deskripsi" required><?= e($edit['deskripsi']??'') ?></textarea></div><div class="form-group"><label>Gambar buku <?= $edit ? '(opsional)' : '(opsional)' ?></label><input type="file" name="gambar" accept="image/jpeg,image/png,image/webp"><span class="helper">JPG, PNG, atau WEBP maksimal 2 MB.</span></div><button type="submit"><?= $edit?'Simpan Perubahan':'Tambah Buku' ?></button><?php if($edit): ?><a class="button button-outline" href="<?= url('admin/buku.php') ?>">Batal</a><?php endif; ?></form></section><section class="card table-wrap"><h2>Daftar Buku</h2><table class="data-table"><thead><tr><th>Buku</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($books as $book): ?><tr><td><b><?= e($book['judul_buku']) ?></b><br><span class="helper"><?= e($book['penulis']) ?></span></td><td><?= e($book['nama_kategori']) ?></td><td><?= rupiah($book['harga']) ?></td><td><?= $book['stok'] ?></td><td><div class="row-actions"><a class="button button-small button-outline" href="<?= url('admin/buku.php?edit='.$book['id_buku']) ?>">Ubah</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id_buku" value="<?= $book['id_buku'] ?>"><button data-confirm="Hapus buku ini?" class="button-danger button-small" type="submit">Hapus</button></form></div></td></tr><?php endforeach; ?></tbody></table></section></div>
